import {el,button,api,sourceList} from './ui.mjs';
import {registerEnterpriseUI,renderApp,openEvidence} from './experience.mjs';
import {createEnterpriseMap} from './enterprise-gpu.mjs';
import {createModeFetch,companyForQuestion,initialEnterpriseMode,enterpriseModeUrl,createPendingActions} from './enterprise-state.mjs';
const $=id=>document.getElementById(id),css=el('link');css.rel='stylesheet';css.href='/enterprise.css';document.head.append(css);
const mode=el('div',null,'enterprise-mode');mode.setAttribute('role','group');mode.setAttribute('aria-label','Map mode');
const travelMode=button('Travel',()=>setMode(false),'enterprise-mode-option'),businessMode=button('Businesses',()=>setMode(true),'enterprise-mode-option');travelMode.setAttribute('aria-pressed','true');businessMode.setAttribute('aria-pressed','false');mode.append(travelMode,businessMode);$('toolbar').append(mode);
const canvas=el('canvas');canvas.id='enterprise-map';canvas.hidden=true;canvas.setAttribute('aria-label','Enterprise offices on the complete WebGPU London map');canvas.tabIndex=0;document.body.prepend(canvas);
const attribution=el('p',null,'enterprise-attribution'),osm=el('a','© OpenStreetMap contributors');osm.href='https://www.openstreetmap.org/copyright';osm.target='_blank';osm.rel='noopener';attribution.append(osm,document.createTextNode(' · Office locations, not entrances'));attribution.hidden=true;$('app-chrome').append(attribution);
const composer=el('form',null,'map-question'),input=el('input'),send=el('button','⌘K');composer.id='business-question-bar';composer.hidden=true;input.id='enterprise-question';input.maxLength=2000;input.placeholder='Ask about a business…';input.setAttribute('aria-label','Ask about a business');send.type='submit';send.setAttribute('aria-label','Ask about this business');composer.append(input,send);$('app-chrome').append(composer);composer.onsubmit=event=>{event.preventDefault();if(busy)return;try{const company=companyForQuestion(input.value,data?.companies||[],selected?.id);if(!company)throw Error('Name a verified business or select its pin first.');assess(company,input.value.trim());}catch(e){notice(e.message);}};
const actions=createPendingActions(()=>renderApp());
const drafts=new Map(),travelExamples=[...$('examples').children],recentKey='mubit-enterprise-recent-correction-v1';
let active=false,data=null,map=null,mapPromise=null,selected=null,result=null,busy=false,sequence=0,correction=null,page='answer',error=null,renderKey=null;
const notice=message=>window.dispatchEvent(new CustomEvent('london:notice',{detail:message}));
const section=(label,text)=>{const box=el('section',null,'business-section');box.append(el('h3',label),el('p',text));return box;};
function companyImage(c,cls='business-thumb'){const frame=el('span',null,cls);if(c.image){const img=el('img');img.src=c.image.url;img.alt=c.image.alt;img.loading='lazy';img.onerror=()=>img.remove();frame.append(img);}else frame.textContent=c.name.split(/[ .]/).filter(Boolean).map(w=>w[0]).slice(0,2).join('');return frame;}
function companySources(c){const box=el('details',null,'sources');box.append(el('summary','Sources & office location'),sourceList(c.sources));const osm=el('a',c.address+' · OpenStreetMap ↗');osm.href=c.osm.url;osm.target='_blank';osm.rel='noopener';box.append(el('p',c.location_precision,'muted'),osm);if(c.image){const credit=el('a',c.image.author+' · '+c.image.license);credit.href=c.image.source_url;credit.target='_blank';credit.rel='noopener';box.append(el('p',null,'business-credit'));box.lastChild.append(credit);}return box;}
function heading(container,title,onClose=closeCard){const h=el('div',null,'answer-heading'),q=el('details',null,'question');q.append(el('summary',title));const close=button('×',onClose,'icon-button');close.setAttribute('aria-label','Close business answer');h.append(q,close);container.append(h);}
function syncMapLayout(){send.disabled=busy;send.textContent=busy?'⌘K':input.value?'⏎':'⌘K';map?.refreshLayout();$('overview').hidden=!active;$('overview').setAttribute('aria-label',active?'Show all businesses':'Show all London');$('overview').title=active?'Show all businesses':'Show all London';}
function render(){
 if(!active)return;const card=$('answer-card'),view=$('answer-view'),learning=$('learning');card.setAttribute('aria-label','Business answer');card.hidden=busy||(!selected&&!error&&page==='answer');view.hidden=page==='edit';learning.hidden=page!=='edit';$('examples').hidden=Boolean(selected||busy||page!=='answer');
 if(card.hidden){view.replaceChildren();syncMapLayout();return;}
 const key=[page,selected?.id,result?.interaction_id,page==='receipt'?correction?.id:''].join(':');if(key!==renderKey){card.scrollTop=0;renderKey=key;}
 if(page==='edit'){renderEditor(learning);syncMapLayout();return;}
 view.replaceChildren();if(page==='receipt'){renderReceipt(view);syncMapLayout();return;}
 heading(view,result?.question||selected?.name||'Business research');if(error){view.append(el('p',error,'form-message'));syncMapLayout();return;}
 if(!selected){syncMapLayout();return;}
 const identity=el('div',null,'business-identity'),copy=el('div');copy.append(el('strong',selected.name),el('small',selected.address));identity.append(companyImage(selected),copy);view.append(identity);
 if(result){const a=result.assessment;view.append(el('p','Fit: '+a.fit+' · '+(a.llm_usage==='public_evidence'?'Public AI evidence; private usage unknown':'LLM adoption unknown'),'state-label'));
 for(const [label,text]of [['Public evidence',a.public_fact],['Recurring workload · hypothesis',a.workload_hypothesis],['Why this fit',a.fit_reason],['Pitch · proposal',a.pitch],['Next conversation',a.discovery_question],['Unknown',a.unknowns],['Pilot success check',a.pilot_measure]])view.append(section(label,text));
 view.append(companySources(selected));const footer=el('div',null,'answer-footer');footer.append(button((result.inference?.label||'Route unverified')+' · '+(result.elapsed_ms/1000).toFixed(1)+' s',()=>openEvidence('answer'),'provenance'),button('Fix this',()=>{page='edit';renderApp();},'text-button'));view.append(footer);
 }else{for(const f of selected.facts)view.append(section('Public fact',f.text));}
 syncMapLayout();
}
function closeCard(){if(busy)return;selected=null;result=null;error=null;page='answer';map?.overview();renderApp();}
function overview(){sequence++;busy=false;closeCard();}
async function assess(company,question){
 const n=++sequence;selected=company;result=null;correction=null;error=null;page='answer';busy=true;map?.select(company);renderApp();
 try{const value=await api('/api/enterprise/assess',{company_id:company.id,question:question||undefined});if(n!==sequence)return;result=value;busy=false;renderApp();}
 catch(e){if(n!==sequence)return;busy=false;error=e.message;renderApp();}
}
globalThis.fetch=createModeFetch(globalThis.fetch.bind(globalThis),()=>active,location.origin);

function renderEditor(box){
 if(!result||!selected)return;box.replaceChildren();const h=el('div',null,'edit-heading');h.append(el('h2','Fix this judgement'),button('×',()=>{page='answer';renderApp();},'icon-button'));box.append(h,el('p',selected.name,'edit-question'));
 const body=el('div',null,'edit-body');body.append(section('Current workload hypothesis',result.assessment.workload_hypothesis));const label=el('label','Your correction'),note=el('textarea');note.id='enterprise-lesson';label.htmlFor=note.id;note.maxLength=2400;note.rows=6;note.value=drafts.get(result.interaction_id)??correction?.note??'';note.oninput=()=>drafts.set(result.interaction_id,note.value);note.placeholder='For this kind of buyer, focus on… Avoid assuming…';body.append(label,note,el('p','Teach a judgement you would reuse. New company facts still need a source.','muted'));box.append(body);
 const source=result,key='save:'+source.interaction_id,pending=actions.has(key),footer=el('div',null,'edit-footer');
 const save=button(pending?'Saving correction…':'Save correction',async()=>{const text=note.value;const saved=await actions.run(key,()=>api('/api/enterprise/corrections',{interaction_id:source.interaction_id,note:text}));drafts.delete(source.interaction_id);try{localStorage.setItem(recentKey,saved.id);}catch{}if(result!==source||page!=='edit')return;correction=saved;page='receipt';renderApp();},'primary');save.disabled=pending;save.setAttribute('aria-busy',String(pending));note.disabled=pending;footer.append(save,el('p','Saved locally first. Teaching is a separate choice.','muted'));box.append(footer);
}
function renderReceipt(box){heading(box,'Your correction',()=>{page='answer';renderApp();});const pending=actions.has('teach:'+correction.id);box.append(section('Judgement to teach',correction.note),el('p',pending?'Teaching request in progress.':correction.detail,'muted'));if(correction.receipt)box.append(el('code',correction.receipt,'business-receipt'));
 if(correction.state==='saved'){const id=correction.id,key='teach:'+id,pending=actions.has(key),teach=button(pending?'Teaching…':'Teach this judgement',async()=>{const received=await actions.run(key,()=>api('/api/enterprise/corrections/'+id+'/teach',{}));if(correction?.id!==id)return;correction=received;renderApp();},'primary');teach.disabled=pending;teach.setAttribute('aria-busy',String(pending));box.append(teach,el('p',pending?'Waiting for a verified Mubit receipt.':'Sends this company evidence, question and correction through Luna via Mubit for review and training.','muted'));}
 if(correction.state==='sending'){const id=correction.id;box.append(button('Refresh receipt',async()=>{const latest=await api('/api/enterprise/corrections/'+id);if(correction?.id!==id)return;correction=latest;renderApp();},'quiet'));}
 if(correction.assessment){const d=el('details',null,'sources');d.append(el('summary','Inspect Luna’s teaching response'),section('Revised hypothesis',correction.assessment.workload_hypothesis),section('Revised pitch',correction.assessment.pitch),el('p','Generated with the correction in context. This is not an adapter result.','muted'));box.append(d);}box.append(button('Training evidence',()=>openEvidence('evaluation'),'text-button'));
}
async function evidence(tab,box){
 box.replaceChildren();if(tab==='businesses'){box.append(el('p','Seven verified London offices. Select a pin or a company to ask about a possible pilot.','muted'));for(const c of data?.companies||[]){const row=button('',()=>{ $('evidence').hidden=true;assess(c);},'place-row business-directory-row'),copy=el('span');copy.append(el('strong',c.name),el('small',c.sector));row.append(companyImage(c),copy);box.append(row);}box.append(el('p','Workloads and pitches are hypotheses. No business has been contacted.','muted'));return;}
 if(tab==='answer'){if(!result){box.append(el('p','Select a business or ask a question to inspect its sources.','muted'));return;}box.append(el('h3',result.inference?.label||'Route unverified'),sourceList(selected.sources));const proof=el('details');proof.append(el('summary','Response and routing evidence'),el('pre',JSON.stringify(result,null,2)));box.append(proof);return;}
 if(tab==='corrections'){let id;try{id=localStorage.getItem(recentKey);}catch{}if(!id){box.append(el('p','Choose Fix this on a business answer to save a correction.','muted'));return;}try{const saved=await api('/api/enterprise/corrections/'+encodeURIComponent(id));box.append(section('Latest saved judgement',saved.note),el('p',saved.detail,'muted'),button('Open correction',()=>{sequence++;busy=false;result=null;error=null;correction=saved;selected=data.companies.find(c=>c.id===saved.company_id);page='receipt';map?.select(selected);$('evidence').hidden=true;renderApp();},'quiet'));}catch(e){box.append(el('p',e.message,'muted'));}return;}
 if(tab==='map'){box.append(el('h3','London map'),el('p','The same complete city geometry and Light control. Business labels connect to verified OpenStreetMap office locations.','muted'));const d=el('details');d.append(el('summary','Renderer and projection evidence'),el('pre',JSON.stringify(globalThis.enterpriseMapProof||{},null,2)));box.append(d);return;}
 if(tab==='evaluation'){try{const s=await api('/api/enterprise/status');box.append(el('h3','Enterprise learning'),el('p',s.detail));if(s.adapter)box.append(el('p',`Qwen3 4B · version ${s.adapter.version} · ${s.adapter.internal_pass}/${s.adapter.internal_total} internal checks`,'muted'));if(s.evaluation){const e=s.evaluation;box.append(el('h4','Fresh development questions'),el('p',e.summary));for(const item of e.cases){const d=el('details');d.append(el('summary',(data.companies.find(c=>c.id===item.company_id)?.name||item.company_id)+' · '+(item.full_task_pass?'Pass':'Needs work')),el('p',item.question),el('p',item.reason),el('p','Required response format: '+(item.contract_pass?'passed':'failed')+'.','muted'),el('pre',item.raw));box.append(d);}box.append(el('p',e.schema_diagnostic,'muted'),el('p',e.limitations,'muted'));}const d=el('details');d.append(el('summary','Full evidence record'),el('pre',JSON.stringify(s,null,2)));box.append(d);}catch(e){box.append(el('p',e.message,'form-message'));}}
}
input.addEventListener('input',()=>{send.textContent=input.value?'⏎':'⌘K';});
registerEnterpriseUI({render,focus:()=>input.focus(),clear:closeCard,overview,edit:()=>{page='edit';renderApp();},evidence});
async function setMode(value){
 if(active!==value)renderKey=null;active=value;document.documentElement.dataset.enterprise=String(value);travelMode.setAttribute('aria-pressed',String(!value));businessMode.setAttribute('aria-pressed',String(value));attribution.hidden=!value;composer.hidden=!value;
 try{localStorage.setItem('mubit-map-mode-v1',value?'enterprise':'travel');history.replaceState(null,'',enterpriseModeUrl(location.href,value));}catch{}
 const tab=$('evidence-tabs').querySelector('[data-tab=businesses]');tab.hidden=!value;$('examples').replaceChildren(...(value?[button('Morgan Stanley',()=>assess(data.companies.find(c=>c.id==='morgan-stanley'))),button('Is Google a fit?',()=>assess(data.companies.find(c=>c.id==='google'),'Is Google a sensible first prospect for Mubit? Give a candid go or no-go.')),button('Browse businesses',()=>openEvidence('businesses'))]:travelExamples));
 renderApp();syncMapLayout();if(!value){map?.setActive(false);return;}
 if(!data){try{data=await api('/api/enterprise/companies');}catch(e){error=e.message;renderApp();return;}}
 if(document.documentElement.dataset.homewardReady!=='true')return;
 try{if(!map){mapPromise??=createEnterpriseMap({canvas,companies:data.companies,onSelect:assess,askState:()=>({focused:document.activeElement===input,busy}),onAskRect:r=>{composer.style.left=r.x+'px';composer.style.top=r.y+'px';composer.style.width=r.width+'px';composer.style.height=r.height+'px';}});map=await mapPromise;}if(active)map.setActive(true);}catch(e){mapPromise=null;notice(e.message);}
}
const restoreMode=()=>{let saved;try{saved=localStorage.getItem('mubit-map-mode-v1');}catch{}if(active||initialEnterpriseMode(location.href,saved))setMode(true);};window.addEventListener('london:ready',restoreMode);if(document.documentElement.dataset.homewardReady==='true')restoreMode();
